import "./Nav.css";

function Nav() {
  return (
    <div className="mainNav">
      <form action="#" className="form">
        <input type="text" placeholder="Username" required value={username} />
        <input
          type="password"
          placeholder="Password"
          value={password}
          required
        />
        <input type="submit" disabled={!username || !password} />
      </form>
    </div>
  );
}

export default Nav;
